internal fun catalanMatchingCount(count: Int, noun: String): String {
    val adjective = when {
        noun == "song" && count == 1 -> "trobada"
        noun == "song" -> "trobades"
        count == 1 -> "trobat"
        else -> "trobats"
    }
    return "${localizedCountLabel(count, noun, AppLanguage.Catalan)} $adjective"
}
